import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { test } from 'node:test';
import { evidenceMap, hasEvidence, overlaps, signalsForSpan } from './evidence';
import { reduce, type CaseView } from './reducer';
import type { Run } from './runs';
import { clockRunning, elapsedAt, elapsedMs } from './selectors';
import { fmtDur, waterfall } from './waterfall';

// Every assertion runs over the REAL recorded runs in public/runs (generated by the real pipeline, plus the live hero recording).
const DIR = new URL('../public/runs/', import.meta.url);
const load = (f: string) => JSON.parse(readFileSync(new URL(f, DIR), 'utf8')) as Run;
const runs = readdirSync(DIR).filter((f) => f.endsWith('.json'));
const hero = (r: Run): CaseView => Object.values(reduce(r.events).cases).find((c) => c.call)!;
const upTo = (r: Run, n: number): CaseView | undefined => Object.values(reduce(r.events.slice(0, n)).cases).find((c) => c.email && c.state !== 'cleared');

test('every run: laps are in order, touch end to end, and add up to the email-to-outcome time the header shows', () => {
  for (const f of runs) {
    const c = hero(load(f));
    const w = waterfall(c)!;
    assert.deepEqual(w.laps.map((l) => l.key), ['detect', 'hold', 'dial', 'call'], f);
    assert.ok(w.done, `${f}: the call has an outcome`);
    for (const [i, l] of w.laps.entries()) {
      assert.ok(l.startMs !== null && l.endMs !== null && l.endMs >= l.startMs, `${f}: ${l.key} is closed and not negative`);
      if (i > 0) assert.equal(l.startMs, w.laps[i - 1].endMs, `${f}: ${l.key} starts where the previous step ended`);
    }
    assert.equal(w.laps.reduce((n, l) => n + (l.endMs! - l.startMs!), 0), w.totalMs, `${f}: laps sum to the total`);
    assert.equal(w.totalMs, elapsedMs(c), `${f}: same number as the case header`);
    assert.equal(w.ramp?.count, 3, `${f}: two bill holds and one vendor hold`);
  }
});

test('the live recording carries the measured numbers: model read 2,014 ms, three Ramp holds 1,279 ms, answered after 20 s, 70 s in total', () => {
  const w = waterfall(hero(load('fraud-live.json')))!;
  assert.equal(w.llmMs, 2014);
  assert.deepEqual(w.ramp, { count: 3, ms: 339 + 523 + 417, mode: 'mock' });
  assert.equal(w.ringMs, 20_000);
  assert.equal(w.totalMs, 70_000);
});

test('generated runs replay with llmMs 0: the waterfall shows no model time rather than a fake one', () => {
  assert.equal(waterfall(hero(load('fraud.json')))!.llmMs, null);
});

test('mid-run the waterfall stops at the last milestone reached and leaves later steps open', () => {
  const r = load('fraud.json');
  const atHeld = waterfall(upTo(r, 30)!)!;      // payment.held is in, the call is not
  assert.equal(atHeld.done, false);
  assert.equal(atHeld.laps[1].endMs, 9900);
  assert.equal(atHeld.laps[2].endMs, null);
  assert.equal(atHeld.laps[3].startMs, null);
  assert.equal(atHeld.totalMs, elapsedMs(upTo(r, 30)!), '"so far" matches the case header while the case is still going');
});

test('a cleared email has one step and no hold, dial or call', () => {
  const c = Object.values(reduce(load('fraud.json').events).cases).find((x) => x.state === 'cleared')!;
  const w = waterfall(c)!;
  assert.deepEqual(w.laps.map((l) => l.key), ['detect']);
  assert.ok(w.done);
});

test('fmtDur', () => {
  assert.equal(fmtDur(0), '0 ms');
  assert.equal(fmtDur(339), '339 ms');
  assert.equal(fmtDur(2014), '2.0 s');
  assert.equal(fmtDur(70_000), '1:10');
});

test('case clock: ticks with wall time only while the case is still working, freezes at call.outcome, never runs backwards', () => {
  const r = load('fraud.json');
  const mid = upTo(r, 34)!;                     // calling
  assert.ok(clockRunning(mid));
  const start = Date.parse(mid.timeline[0].ts);
  assert.equal(elapsedAt(mid), elapsedMs(mid), 'replays pass no clock and follow the events');
  assert.equal(elapsedAt(mid, start + 90_000), 90_000);
  assert.equal(elapsedAt(mid, start - 5_000), elapsedMs(mid), 'a skewed clock never shows less than the events already prove');
  const end = hero(r);
  assert.ok(!clockRunning(end));
  assert.equal(elapsedAt(end, Date.now() + 1e9), 40_000, 'frozen at the outcome');
});

test('evidence links: the routing number span points at both bank signals; sender signals point at the From domain', () => {
  const c = hero(load('fraud.json'));
  const routing = c.signals.find((s) => s.id === 'bank_details_differ')!.spans[0];
  assert.deepEqual(signalsForSpan(c, routing.start, routing.end).sort(), ['bank_details_differ', 'bank_details_present']);
  const m = evidenceMap(c);
  assert.ok(m.from.includes('sender_domain_not_on_file'));
  assert.ok(hasEvidence(m, 'bank_change_language'));
  assert.ok(!hasEvidence(m, 'sender_not_known_contact'), 'a signal with nothing to point at is not linkable');
  assert.ok(overlaps(['a', 'b'], ['b']));
  assert.ok(!overlaps(['a'], null));
});
